import re

def count_words(text):
    words = text.split()
    counts = {}
    for word in words:
        cleaned = re.sub(r'[^a-z]', '', word.lower())
        if cleaned:
            counts[cleaned] = counts.get(cleaned, 0) + 1
    return counts
```

